// Input: $json.all_pages = [{page_url, page_html, page_title, ad_snippets, page_source, ...}, ...]

function normUrl(u) {
  if (!u || typeof u !== "string") return "";
  return u.trim().replace(/&amp;/g, "&");
}

function uniqBy(arr, keyFn) {
  const seen = new Set();
  const out = [];
  for (const x of arr) {
    const k = keyFn(x);
    if (!k || seen.has(k)) continue;
    seen.add(k);
    out.push(x);
  }
  return out;
}

function extractFromHtml(html) {
  const candidates = [];
  if (!html || typeof html !== "string") return candidates;

  // meta og:image / twitter:image
  for (const re of [
    /<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["'][^>]*>/gi,
    /<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["'][^>]*>/gi,
  ]) {
    let m;
    while ((m = re.exec(html)) !== null) {
      candidates.push({ url: normUrl(m[1]), kind: "meta" });
    }
  }

  // img src + alt
  {
    const re = /<img[^>]+>/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
      const tag = m[0];
      const src = (tag.match(/\ssrc=["']([^"']+)["']/i) || [])[1];
      const alt = (tag.match(/\salt=["']([^"']*)["']/i) || [])[1] || "";
      const cls = (tag.match(/\sclass=["']([^"']*)["']/i) || [])[1] || "";
      const w = (tag.match(/\swidth=["']([^"']+)["']/i) || [])[1] || "";
      const h = (tag.match(/\sheight=["']([^"']+)["']/i) || [])[1] || "";
      if (src) candidates.push({ url: normUrl(src), kind: "img", alt, cls, w, h });
    }
  }

  // srcset candidates (take the largest descriptor)
  {
    const re = /\ssrcset=["']([^"']+)["']/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
      const srcset = m[1];
      const parts = srcset.split(",").map(s => s.trim()).filter(Boolean);
      // prefer last (often largest), but also grab all urls for recall
      for (const p of parts) {
        const u = p.split(/\s+/)[0];
        if (u) candidates.push({ url: normUrl(u), kind: "srcset" });
      }
    }
  }

  // inline svg (potential logo)
  if (/<svg[\s>]/i.test(html)) {
    candidates.push({ url: "__INLINE_SVG__", kind: "svg_inline" });
  }

  return candidates;
}

const pages = Array.isArray($json.all_pages) ? $json.all_pages : [];
const out = [];

for (const p of pages) {
  const page_url = p.page_url || "";
  const page_title = p.page_title || "";
  const page_source = p.page_source || "";
  const html = p.page_html || "";

  const raw = extractFromHtml(html).map(c => ({
    url: c.url,
    kind: c.kind,
    alt: c.alt || "",
    cls: c.cls || "",
    source_page: page_url,
    page_title,
    page_source,
  }));

  // Basic filtering: remove empties, data URIs, likely tracking pixels
  const filtered = raw.filter(x =>
    x.url &&
    typeof x.url === "string" &&
    !x.url.startsWith("data:") &&
    !x.url.includes("doubleclick") &&
    !x.url.includes("googletagmanager")
  );

  out.push(...filtered);
}

// Deduplicate by url+kind+source_page
let candidates = uniqBy(out, x => `${x.kind}|${x.source_page}|${x.url}`);

// Hard cap for safety (keeps LLM prompt bounded)
candidates = candidates.slice(0, 250);

const input = $input.first().json;
return [{
  page_summaries: input.page_summaries || [],
  tier2_page_summaries: input.tier2_page_summaries || [],
  tier2_decision: input.tier2_decision || {},
  asset_candidates: candidates
}];

